package ir.orix.school.assessment.domain;
import java.time.Instant;
import jakarta.persistence.*; import ir.orix.school.enrollment.domain.Enrollment; import ir.orix.school.organization.domain.Tenant; import ir.orix.school.people.domain.StudentProfile; import ir.orix.school.shared.persistence.AuditedEntity;
@Entity @Table(name="assessment_participant",schema="school")
public class AssessmentParticipant extends AuditedEntity { public enum Status{ELIGIBLE,REMOVED} @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_id") private Assessment assessment; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="student_id") private StudentProfile student; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="enrollment_id") private Enrollment enrollment; @Column(name="student_name_snapshot",nullable=false,length=250) private String studentNameSnapshot; @Column(name="student_code_snapshot",nullable=false,length=50) private String studentCodeSnapshot; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private Status status; @Column(name="fee_paid_at") private Instant feePaidAt; protected AssessmentParticipant(){} public AssessmentParticipant(Tenant tenant,Assessment assessment,Enrollment enrollment){this.tenant=tenant;this.assessment=assessment;this.enrollment=enrollment;this.student=enrollment.getStudent();this.studentNameSnapshot=student.getPerson().getFullName();this.studentCodeSnapshot=student.getStudentCode();this.status=Status.ELIGIBLE;} public Assessment getAssessment(){return assessment;} public StudentProfile getStudent(){return student;} public Enrollment getEnrollment(){return enrollment;} public String getStudentNameSnapshot(){return studentNameSnapshot;} public String getStudentCodeSnapshot(){return studentCodeSnapshot;} public Status getStatus(){return status;} public Instant getFeePaidAt(){return feePaidAt;} public boolean isFeePaid(long priceRial){return priceRial<=0||feePaidAt!=null;} public void markFeePaid(Instant when){this.feePaidAt=when;} }
